+<!DOCTYPE html>
+<html lang="en">
+<head>
+<meta charset="UTF-8">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<title>TodoMVC</title>
+<style>
+  * { box-sizing: border-box; }
+  body { font: 16px "Helvetica Neue", Helvetica, Arial, sans-serif; background: #f5f5f5; color: #111; margin: 0; }
+  h1 { text-align: center; font-size: 80px; font-weight: 200; color: #b83f45; margin: 40px 0 20px; }
+  .app { max-width: 550px; margin: 0 auto 40px; background: #fff; box-shadow: 0 2px 4px rgba(0,0,0,.2), 0 25px 50px rgba(0,0,0,.1); }
+  .header { display: flex; align-items: center; border-bottom: 1px solid #e6e6e6; }
+  .toggle-all { width: 45px; text-align: center; cursor: pointer; color: #737373; font-size: 22px; border: 0; background: none; padding: 0; height: 60px; }
+  .toggle-all.hidden { visibility: hidden; }
+  .toggle-all.on { color: #484848; }
+  .new-todo { flex: 1; padding: 16px 16px 16px 0; font-size: 24px; border: 0; outline: none; font-style: normal; }
+  .new-todo::placeholder { font-style: italic; color: #999; }
+  ul { list-style: none; margin: 0; padding: 0; }
+  li { display: flex; align-items: center; border-bottom: 1px solid #ededed; font-size: 24px; position: relative; }
+  li .check { width: 45px; height: 40px; margin: 0; cursor: pointer; accent-color: #5dc2af; }
+  li label { flex: 1; padding: 15px 50px 15px 10px; word-break: break-word; line-height: 1.2; transition: color .2s; }
+  li.completed label { color: #949494; text-decoration: line-through; }
+  li .destroy { position: absolute; right: 10px; border: 0; background: none; font-size: 30px; color: #949494; cursor: pointer; display: none; }
+  li .destroy:hover { color: #c18585; }
+  li:hover .destroy, li .destroy:focus { display: block; }
+  li .edit { flex: 1; font-size: 24px; padding: 12px 16px; margin-left: 45px; border: 1px solid #999; box-shadow: inset 0 -1px 5px rgba(0,0,0,.2); }
+  li.editing .check, li.editing label, li.editing .destroy { display: none; }
+  .footer { display: flex; justify-content: space-between; align-items: center; padding: 10px 15px; font-size: 14px; color: #111; gap: 8px; flex-wrap: wrap; }
+  .filters { display: flex; gap: 6px; }
+  .filters a { color: inherit; text-decoration: none; padding: 3px 7px; border: 1px solid transparent; border-radius: 3px; }
+  .filters a:hover { border-color: #ebd5d5; }
+  .filters a.selected { border-color: #ce4646; }
+  .clear-completed { border: 0; background: none; cursor: pointer; color: inherit; font-size: 14px; }
+  .clear-completed:hover { text-decoration: underline; }
+  .hidden { display: none !important; }
+  .info { text-align: center; color: #4d4d4d; font-size: 11px; }
+</style>
+</head>
+<body>
+<h1>todos</h1>
+<section class="app">
+  <div class="header">
+    <button class="toggle-all" title="Mark all as complete" aria-label="Mark all as complete">❯</button>
+    <input class="new-todo" placeholder="What needs to be done?" autofocus aria-label="New todo">
+  </div>
+  <ul class="todo-list"></ul>
+  <footer class="footer">
+    <span class="todo-count"></span>
+    <nav class="filters">
+      <a href="#/">All</a>
+      <a href="#/active">Active</a>
+      <a href="#/completed">Completed</a>
+    </nav>
+    <button class="clear-completed">Clear completed</button>
+  </footer>
+</section>
+<p class="info">Double-click to edit a todo</p>
+
+<script>
+(() => {
+  const STORAGE_KEY = 'todomvc-plain-js';
+  const $ = (s) => document.querySelector(s);
+  const list = $('.todo-list'), input = $('.new-todo'), footer = $('.footer');
+  const toggleAll = $('.toggle-all'), count = $('.todo-count'), clearBtn = $('.clear-completed');
+
+  let todos;
+  try { todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || []; } catch { todos = []; }
+  let editingId = null;
+
+  const save = () => localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
+  const filter = () => (location.hash.replace('#/', '') || 'all');
+  const uid = () => Date.now().toString(36) + Math.random().toString(36).slice(2);
+
+  function render() {
+    const f = filter();
+    const visible = todos.filter(t => f === 'active' ? !t.completed : f === 'completed' ? t.completed : true);
+    list.innerHTML = '';
+    for (const t of visible) {
+      const li = document.createElement('li');
+      li.dataset.id = t.id;
+      if (t.completed) li.classList.add('completed');
+      if (t.id === editingId) {
+        li.classList.add('editing');
+        const edit = document.createElement('input');
+        edit.className = 'edit';
+        edit.value = t.title;
+        li.append(edit);
+        requestAnimationFrame(() => { edit.focus(); edit.setSelectionRange(edit.value.length, edit.value.length); });
+      } else {
+        const cb = document.createElement('input');
+        cb.type = 'checkbox'; cb.className = 'check'; cb.checked = t.completed;
+        cb.setAttribute('aria-label', 'Toggle ' + t.title);
+        const label = document.createElement('label');
+        label.textContent = t.title;
+        const del = document.createElement('button');
+        del.className = 'destroy'; del.textContent = '×';
+        del.setAttribute('aria-label', 'Delete ' + t.title);
+        li.append(cb, label, del);
+      }
+      list.append(li);
+    }
+    const active = todos.filter(t => !t.completed).length;
+    const completed = todos.length - active;
+    count.innerHTML = `<strong>${active}</strong> item${active === 1 ? '' : 's'} left`;
+    footer.classList.toggle('hidden', todos.length === 0);
+    toggleAll.classList.toggle('hidden', todos.length === 0);
+    toggleAll.classList.toggle('on', todos.length > 0 && active === 0);
+    clearBtn.classList.toggle('hidden', completed === 0);
+    document.querySelectorAll('.filters a').forEach(a =>
+      a.classList.toggle('selected', a.getAttribute('href') === '#/' + (f === 'all' ? '' : f)));
+    save();
+  }
+
+  const findId = (el) => el.closest('li')?.dataset.id;
+
+  input.addEventListener('keydown', (e) => {
+    if (e.key !== 'Enter') return;
+    const title = input.value.trim();
+    if (!title) return;
+    todos.push({ id: uid(), title, completed: false });
+    input.value = '';
+    render();
+  });
+
+  list.addEventListener('change', (e) => {
+    if (!e.target.classList.contains('check')) return;
+    const t = todos.find(t => t.id === findId(e.target));
+    t.completed = e.target.checked;
+    render();
+  });
+
+  list.addEventListener('click', (e) => {
+    if (!e.target.classList.contains('destroy')) return;
+    const id = findId(e.target);
+    todos = todos.filter(t => t.id !== id);
+    render();
+  });
+
+  list.addEventListener('dblclick', (e) => {
+    if (e.target.tagName !== 'LABEL') return;
+    editingId = findId(e.target);
+    render();
+  });
+
+  function finishEdit(el, cancel) {
+    if (editingId === null) return;
+    const t = todos.find(t => t.id === editingId);
+    editingId = null;
+    if (!cancel && t) {
+      const title = el.value.trim();
+      if (title) t.title = title; else todos = todos.filter(x => x !== t);
+    }
+    render();
+  }
+
+  list.addEventListener('keydown', (e) => {
+    if (!e.target.classList.contains('edit')) return;
+    if (e.key === 'Enter') finishEdit(e.target, false);
+    else if (e.key === 'Escape') finishEdit(e.target, true);
+  });
+  list.addEventListener('focusout', (e) => {
+    if (e.target.classList.contains('edit')) finishEdit(e.target, false);
+  });
+
+  toggleAll.addEventListener('click', () => {
+    const allDone = todos.every(t => t.completed);
+    todos.forEach(t => t.completed = !allDone);
+    render();
+  });
+
+  clearBtn.addEventListener('click', () => {
+    todos = todos.filter(t => !t.completed);
+    render();
+  });
+
+  window.addEventListener('hashchange', render);
+  render();
+})();
+</script>
+</body>
+</html>
